  CommentId,
  IssueId,
  MemberId,
  MilestoneId,
  OrgId,
  ProjectId,
  UserId,
  IsoTimestamp,
} from "./common";

"project.restored": EventEnvelope & { projectId: ProjectId };
"milestone.created": EventEnvelope & {
  milestoneId: MilestoneId;
  projectId: ProjectId;
};
"milestone.reopened": EventEnvelope & {
  milestoneId: MilestoneId;
  projectId: ProjectId;
};
"milestone.closed": EventEnvelope & {
  milestoneId: MilestoneId;
  projectId: ProjectId;
  movedToMilestoneId: MilestoneId | null;
  movedIssueIds: readonly IssueId[];
};
"issue.created": EventEnvelope & {

export const projectIdSchema = brandedId<ProjectId>("projectId");
export const milestoneIdSchema = brandedId<MilestoneId>("milestoneId");
export const issueIdSchema = brandedId<IssueId>("issueId");

  dueAt: isoTimestampSchema.nullable().default(null),
  labelIds: z.array(labelIdSchema).max(20).default([]),
  milestoneId: milestoneIdSchema.nullable().default(null),
});

import { z } from "zod";
import {
  isoTimestampSchema,
  issueIdSchema,
  milestoneIdSchema,
  orgIdSchema,
  projectIdSchema,
} from "./common";

