/**
 * Milestone rows for one project: open and closed, plus the issue counts that
 * describe how far each has come.
 */
import { and, asc, count, eq, inArray, isNull, notInArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { normalizeMilestoneName } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

const EMPTY_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/**
 * Open milestones first, then closed. Within each group the earliest target
 * date comes first, milestones without one come last, and ties break by
 * creation, oldest first.
 */
export async function listMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(
      sql`(case when ${milestones.closedAt} is null then 0 else 1 end)`,
      sql`(case when ${milestones.targetDate} is null then 1 else 0 end)`,
      asc(milestones.targetDate),
      asc(milestones.createdAt),
      asc(milestones.id),
    )
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** True when another milestone in the project already uses this name. */
export async function milestoneNameTaken(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): Promise<boolean> {
  const normalized = normalizeMilestoneName(name);
  const rows = getDb()
    .select({ id: milestones.id, name: milestones.name })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .all();

  return rows.some(
    (row) =>
      row.id !== exceptId && normalizeMilestoneName(row.name) === normalized,
  );
}

export async function insertMilestone(input: {
  orgId: OrgId;
  projectId: ProjectId;
  name: string;
  targetDate: IsoTimestamp | null;
  now: IsoTimestamp;
}): Promise<Milestone> {
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: input.now,
      updatedAt: input.now,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: { name?: string; targetDate?: IsoTimestamp | null },
  now: IsoTimestamp,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.targetDate === undefined ? {} : { targetDate: patch.targetDate }),
      updatedAt: now,
    })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function setMilestoneClosedAt(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp | null,
  now: IsoTimestamp,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: now })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Moves a milestone's open live issues, then marks the milestone closed.
 * Both writes commit together; a failure leaves the milestone and its issues
 * where they were.
 */
export function closeMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
  closedAt: IsoTimestamp,
): { milestone: Milestone; movedIssueIds: readonly MilestoneId[] extends never
  ? never
  : readonly import("@/types/common").IssueId[] } {
  return getDb().transaction((tx) => {
    const moved = tx
      .update(issues)
      .set({ milestoneId: moveTo, updatedAt: closedAt })
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.milestoneId, milestoneId),
          isNull(issues.archivedAt),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      )
      .returning({ id: issues.id })
      .all();

    const row = tx
      .update(milestones)
      .set({ closedAt, updatedAt: closedAt })
      .where(
        and(
          orgPredicate(milestones.orgId, orgId),
          eq(milestones.id, milestoneId),
        ),
      )
      .returning()
      .get();

    if (!row) throw new Error(`Milestone ${milestoneId} not found`);

    return {
      milestone: toMilestone(row),
      movedIssueIds: moved.map((entry) => entry.id as import("@/types/common").IssueId),
    };
  });
}

/** Live-issue totals for the given milestones. Missing ids count as empty. */
export async function progressFor(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<ReadonlyMap<string, MilestoneProgress>> {
  const progress = new Map<string, MilestoneProgress>();
  for (const id of milestoneIds) progress.set(id, { ...EMPTY_PROGRESS });
  if (milestoneIds.length === 0) return progress;

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.milestoneId, [...milestoneIds]),
        isNull(issues.archivedAt),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const current = progress.get(row.milestoneId) ?? { ...EMPTY_PROGRESS };
    const closed = CLOSED_ISSUE_STATUSES.includes(row.status);
    progress.set(row.milestoneId, {
      total: current.total + row.value,
      open: current.open + (closed ? 0 : row.value),
      closed: current.closed + (closed ? row.value : 0),
    });
  }

  return progress;
}

/**
 * Milestone lifecycle for a project: create, rename, retarget, close, reopen
 * and the progress a reader sees.
 *
 * Closing moves the milestone's open live issues. Audit rows and the
 * notification fan-out hang off the events published here, so a refusal
 * returns before either is announced.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import "./activity-service";
import "./notification-service";

import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { NotFoundError, projectResource, requireFound } from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import { toIsoTimestamp } from "@/types/common";
import type { MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { IssueId } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";

function stampNow(): ReturnType<typeof toIsoTimestamp> {
  return toIsoTimestamp(new Date());
}

function isOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  nowMs: number,
): boolean {
  if (milestone.closedAt !== null) return false;
  if (milestone.targetDate === null) return false;
  if (progress.open === 0) return false;
  return new Date(milestone.targetDate).getTime() < nowMs;
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  nowMs: number,
): MilestoneWithProgress {
  return {
    milestone,
    progress,
    overdue: isOverdue(milestone, progress, nowMs),
  };
}

async function requireProject(
  orgId: OrgId,
  projectId: ProjectId,
) {
  return requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = await requireProject(input.orgId, input.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (await milestoneRepo.milestoneNameTaken(input.orgId, input.projectId, input.name, null)) {
    throw new MilestoneStateError("name_taken");
  }

  const open = await milestoneRepo.countOpenMilestones(input.orgId, input.projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }

  const now = stampNow();
  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: input.projectId,
    name: input.name,
    targetDate: input.targetDate ?? null,
    now,
  });

  await emit("milestone.created", {
    orgId: actor.orgId,
    actorId: actor.userId,
    occurredAt: now,
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  const project = await requireProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (
    input.name !== undefined &&
    (await milestoneRepo.milestoneNameTaken(
      input.orgId,
      milestone.projectId,
      input.name,
      milestone.id,
    ))
  ) {
    throw new MilestoneStateError("name_taken");
  }

  return milestoneRepo.updateMilestone(
    input.orgId,
    milestone.id,
    { name: input.name, targetDate: input.targetDate },
    stampNow(),
  );
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  const project = await requireProject(input.orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  const moveTo = input.moveOpenIssuesTo ?? null;
  if (moveTo !== null) {
    if (moveTo === milestone.id) {
      throw new NotFoundError("Milestone", moveTo);
    }
    const target = requireFound(
      await milestoneRepo.findMilestoneById(input.orgId, moveTo),
      "Milestone",
      moveTo,
    );
    if (target.projectId !== milestone.projectId) {
      throw new NotFoundError("Milestone", moveTo);
    }
    if (target.closedAt !== null) {
      throw new MilestoneStateError("closed");
    }
  }

  const now = stampNow();
  const closed = milestoneRepo.closeMilestone(
    input.orgId,
    milestone.id,
    moveTo,
    now,
  );

  await emit("milestone.closed", {
    orgId: actor.orgId,
    actorId: actor.userId,
    occurredAt: now,
    milestoneId: closed.milestone.id,
    projectId: closed.milestone.projectId,
    movedToMilestoneId: moveTo,
    movedIssueIds: closed.movedIssueIds,
  });

  return closed;
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await requireProject(orgId, milestone.projectId);
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (milestone.closedAt === null) {
    throw new MilestoneStateError("already_open");
  }

  const open = await milestoneRepo.countOpenMilestones(orgId, milestone.projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }

  const now = stampNow();
  const reopened = await milestoneRepo.setMilestoneClosedAt(
    orgId,
    milestone.id,
    null,
    now,
  );

  await emit("milestone.reopened", {
    orgId: actor.orgId,
    actorId: actor.userId,
    occurredAt: now,
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = await requireProject(orgId, projectId);
  assertCan(actor, "project:read", projectResource(project));

  const nowMs = Date.now();
  const rows = await milestoneRepo.listMilestones(orgId, projectId);
  const progress = await milestoneRepo.progressFor(
    orgId,
    rows.map((row) => row.id),
  );

  return rows.map((milestone) =>
    withProgress(
      milestone,
      progress.get(milestone.id) ?? { total: 0, open: 0, closed: 0 },
      nowMs,
    ),
  );
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await requireProject(orgId, milestone.projectId);
  assertCan(actor, "project:read", projectResource(project));

  const progress = await milestoneRepo.progressFor(orgId, [milestone.id]);
  return withProgress(
    milestone,
    progress.get(milestone.id) ?? { total: 0, open: 0, closed: 0 },
    Date.now(),
  );
}

