/**
 * Milestone audit is attached when this module loads, the same way the
 * notification fan-out is. `registerActivityListeners` stays free to be called
 * again without writing a second row for the same milestone event.
 */
let milestoneAuditRegistered = false;

function registerMilestoneAudit(): void {
  if (milestoneAuditRegistered) return;
  milestoneAuditRegistered = true;

  subscribe("milestone.created", (payload) =>
    record(payload.orgId, "milestone.created", {
      actorId: payload.actorId,
      subjectKind: "milestone",
      subjectId: payload.milestoneId,
      projectId: payload.projectId,
      summary: `Created milestone ${payload.milestoneId}`,
    }).then(() => undefined),
  );

  subscribe("milestone.reopened", (payload) =>
    record(payload.orgId, "milestone.reopened", {
      actorId: payload.actorId,
      subjectKind: "milestone",
      subjectId: payload.milestoneId,
      projectId: payload.projectId,
      summary: `Reopened milestone ${payload.milestoneId}`,
    }).then(() => undefined),
  );

  subscribe("milestone.closed", (payload) =>
    record(payload.orgId, "milestone.closed", {
      actorId: payload.actorId,
      subjectKind: "milestone",
      subjectId: payload.milestoneId,
      projectId: payload.projectId,
      summary: `Closed milestone ${payload.milestoneId}`,
      metadata: {
        movedToMilestoneId: payload.movedToMilestoneId,
        movedIssueCount: payload.movedIssueIds.length,
      },
    }).then(() => undefined),
  );
}

registerMilestoneAudit();

subscribe("milestone.closed", async (payload) => {
  for (const issueId of payload.movedIssueIds) {
    const issue = await issueRepo.findIssueById(payload.orgId, issueId);
    if (!issue || issue.assigneeId === null) continue;

    const destination =
      payload.movedToMilestoneId === null
        ? "out of its milestone"
        : "to another milestone";

    await notify(
      payload.orgId,
      "issue_milestone_changed",
      [issue.assigneeId],
      {
        title: "An issue changed milestone",
        body: `Issue ${issue.number} moved ${destination}`,
        href: `/issues/${issueId}`,
        actorId: payload.actorId,
      },
    );
  }
});

