/**
 * Puts an issue in an open milestone of its own project, moves it to another,
 * or takes it out. A refusal writes nothing.
 */
export async function setIssueMilestone(
  actor: Actor,
  input: SetIssueMilestoneInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, issue.projectId),
    "Project",
    issue.projectId,
  );
  assertNotArchived("Project", project.id, project);

  if (input.milestoneId !== null) {
    await requireOpenMilestoneInProject(
      input.orgId,
      issue.projectId,
      input.milestoneId,
    );
  }

  return issueRepo.setIssueMilestone(
    input.orgId,
    issue.id,
    input.milestoneId,
  );
}

async function requireOpenMilestoneInProject(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): Promise<void> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  if (milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }
}

