/**
 * Behavioral check for project milestones. Not part of the app.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { count, eq } from "drizzle-orm";

const dir = mkdtempSync(join(tmpdir(), "ms-smoke-"));
process.env.TASKFLOW_DB_PATH = join(dir, "taskflow.db");

const { runMigrations } = await import("@/server/db/migrate");
await runMigrations(process.env.TASKFLOW_DB_PATH);

const { MAX_OPEN_MILESTONES_PER_PROJECT } = await import("@/config/constants");
const { subscribe, subscriberCount } = await import("@/lib/event-bus");
const { toAppError, isDomainError } = await import("@/lib/errors");
const { MilestoneStateError } = await import("@/lib/milestones");
const { PermissionDeniedError } = await import("@/lib/permissions");
const { AlreadyArchivedError } = await import("@/lib/soft-delete");
const { TenantScopeError } = await import("@/lib/tenant");
const {
  activityFilterSchema,
} = await import("@/schemas/activity");
const {
  closeMilestoneSchema,
  createMilestoneSchema,
  updateMilestoneSchema,
} = await import("@/schemas/milestone");
const { updateNotificationPreferenceSchema } = await import(
  "@/schemas/notification"
);
const { activityEvents, getDb, issues, notifications } = await import(
  "@/server/db"
);
const { registerActivityListeners } = await import(
  "@/server/services/activity-service"
);
const * as issueService = await import("@/server/services/issue-service");
const * as milestoneService = await import(
  "@/server/services/milestone-service"
);
const * as notificationService = await import(
  "@/server/services/notification-service"
);
const * as projectService = await import("@/server/services/project-service");
const { NotFoundError } = await import("@/server/services/_support");
const { toIsoTimestamp } = await import("@/types/common");
const { createTenant, issueInput } = await import(
  "./server/_support/fixtures.ts"
);

registerActivityListeners();
registerActivityListeners();

function fail(message: string): never {
  throw new Error(message);
}

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) fail(message);
}

async function expectThrow(
  run: () => Promise<unknown>,
  ctor: new (...args: never[]) => Error,
  check?: (error: Error) => void,
): Promise<void> {
  try {
    await run();
  } catch (error) {
    if (!(error instanceof ctor)) {
      fail(
        `expected ${ctor.name}, got ${error instanceof Error ? error.stack : String(error)}`,
      );
    }
    check?.(error);
    return;
  }
  fail(`expected ${ctor.name}, got a result`);
}

function audits(action?: string) {
  const rows = getDb().select().from(activityEvents).all();
  return action === undefined
    ? rows
    : rows.filter((row) => row.action === action);
}

function milestoneAlerts() {
  return getDb()
    .select()
    .from(notifications)
    .where(eq(notifications.kind, "issue_milestone_changed"))
    .all();
}

function issueRows() {
  return getDb().select().from(issues).all();
}

const tenant = await createTenant("milestones", "growth");
const other = await createTenant("milestones-other", "growth");
const member = tenant.actors.member;
const admin = tenant.actors.admin;
const viewer = tenant.actors.viewer;
const orgId = tenant.org.id;

assert(
  subscriberCount("milestone.created") === 1,
  `milestone.created subscribers ${subscriberCount("milestone.created")}`,
);
assert(
  subscriberCount("milestone.reopened") === 1,
  `milestone.reopened subscribers ${subscriberCount("milestone.reopened")}`,
);
assert(
  subscriberCount("milestone.closed") === 2,
  `milestone.closed subscribers ${subscriberCount("milestone.closed")} (audit + fan-out)`,
);

const createdEvents: unknown[] = [];
const reopenedEvents: unknown[] = [];
const closedEvents: unknown[] = [];
const issueCreatedEvents: unknown[] = [];
const issueUpdatedEvents: unknown[] = [];
subscribe("milestone.created", (payload) => {
  createdEvents.push(payload);
});
subscribe("milestone.reopened", (payload) => {
  reopenedEvents.push(payload);
});
subscribe("milestone.closed", (payload) => {
  closedEvents.push(payload);
});
subscribe("issue.created", (payload) => {
  issueCreatedEvents.push(payload);
});
subscribe("issue.updated", (payload) => {
  issueUpdatedEvents.push(payload);
});

const stateError = new MilestoneStateError("name_taken");
assert(stateError.code === "conflict", "code");
assert(isDomainError(stateError), "isDomainError");
const mapped = toAppError(stateError);
assert(mapped.code === "conflict" && mapped.meta?.reason === "name_taken", "toAppError");

assert(
  createMilestoneSchema.parse({
    orgId,
    projectId: tenant.project.id,
    name: "Schema",
  }).targetDate === null,
  "create schema default target",
);
assert(
  closeMilestoneSchema.parse({
    orgId,
    milestoneId: "01HZZZMMMMMMMMMMMMMMMMMMMM",
  }).moveOpenIssuesTo === null,
  "close schema default move",
);
activityFilterSchema.parse({
  orgId,
  action: ["milestone.created", "milestone.closed", "milestone.reopened"],
  subjectKind: "milestone",
  limit: 10,
  cursor: null,
});
updateNotificationPreferenceSchema.parse({
  orgId,
  userId: tenant.userIds.member,
  kind: "issue_milestone_changed",
  inApp: true,
  email: false,
  digestOnly: false,
});

async function makeProject(slug: string, key: string) {
  return projectService.createProject(member, {
    orgId,
    name: slug,
    slug,
    key,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

const past = toIsoTimestamp(new Date(Date.now() - 3 * 86_400_000));
const midPast = toIsoTimestamp(new Date(Date.now() - 86_400_000));
const soon = toIsoTimestamp(new Date(Date.now() + 86_400_000));
const later = toIsoTimestamp(new Date(Date.now() + 10 * 86_400_000));

const orderProject = await makeProject("order", "ORD");
const closedEarly = await milestoneService.createMilestone(member, {
  orgId,
  projectId: orderProject.id,
  name: "closed-early",
  targetDate: past,
});
await milestoneService.closeMilestone(admin, {
  orgId,
  milestoneId: closedEarly.id,
  moveOpenIssuesTo: null,
});
const openNoDate = await milestoneService.createMilestone(member, {
  orgId,
  projectId: orderProject.id,
  name: "open-none",
  targetDate: null,
});
const openLate = await milestoneService.createMilestone(member, {
  orgId,
  projectId: orderProject.id,
  name: "open-late",
  targetDate: later,
});
const openEarly = await milestoneService.createMilestone(member, {
  orgId,
  projectId: orderProject.id,
  name: "open-early",
  targetDate: soon,
});
const closedNoDate = await milestoneService.createMilestone(member, {
  orgId,
  projectId: orderProject.id,
  name: "closed-none",
  targetDate: null,
});
await milestoneService.closeMilestone(admin, {
  orgId,
  milestoneId: closedNoDate.id,
  moveOpenIssuesTo: null,
});
const openNoDate2 = await milestoneService.createMilestone(member, {
  orgId,
  projectId: orderProject.id,
  name: "open-none-2",
  targetDate: null,
});
const closedMid = await milestoneService.createMilestone(member, {
  orgId,
  projectId: orderProject.id,
  name: "closed-mid",
  targetDate: midPast,
});
await milestoneService.closeMilestone(admin, {
  orgId,
  milestoneId: closedMid.id,
  moveOpenIssuesTo: null,
});
const openSame = await milestoneService.createMilestone(member, {
  orgId,
  projectId: orderProject.id,
  name: "open-same",
  targetDate: soon,
});

const listed = await milestoneService.listMilestones(
  viewer,
  orgId,
  orderProject.id,
);
assert(
  listed.map((row) => row.milestone.name).join(",") ===
    "open-early,open-same,open-late,open-none,open-none-2,closed-early,closed-mid,closed-none",
  `order ${listed.map((row) => row.milestone.name).join(",")}`,
);
assert(
  listed.every((row) => row.overdue === false),
  "empty or future milestones are not overdue",
);

const renamed = await milestoneService.updateMilestone(member, {
  orgId,
  milestoneId: openSame.id,
  name: "  OPEN-SAME  ",
});
assert(renamed.name === "  OPEN-SAME  ", "stores the name as given");
assert(renamed.targetDate === soon, "rename keeps the target date");
const cleared = await milestoneService.updateMilestone(member, {
  orgId,
  milestoneId: openSame.id,
  targetDate: null,
});
assert(cleared.targetDate === null, "clears the target date");
await milestoneService.updateMilestone(member, {
  orgId,
  milestoneId: openSame.id,
  name: "open-same",
  targetDate: soon,
});

await expectThrow(
  () =>
    milestoneService.createMilestone(member, {
      orgId,
      projectId: orderProject.id,
      name: "  Open-Early ",
      targetDate: null,
    }),
  MilestoneStateError,
  (error) => {
    assert(
      error instanceof MilestoneStateError && error.reason === "name_taken",
      "name reason",
    );
  },
);
await expectThrow(
  () =>
    milestoneService.updateMilestone(member, {
      orgId,
      milestoneId: openLate.id,
      name: "open-none",
    }),
  MilestoneStateError,
  (error) => {
    assert(
      error instanceof MilestoneStateError && error.reason === "name_taken",
      "rename reason",
    );
  },
);
const lateAfter = await milestoneService.getMilestone(member, orgId, openLate.id);
assert(lateAfter.milestone.name === "open-late", "failed rename changes nothing");

const otherProject = await makeProject("other", "OTH");
const otherName = await milestoneService.createMilestone(member, {
  orgId,
  projectId: otherProject.id,
  name: "open-early",
  targetDate: null,
});
assert(otherName.projectId === otherProject.id, "same name in another project");

await expectThrow(
  () =>
    milestoneService.reopenMilestone(member, orgId, openEarly.id),
  MilestoneStateError,
  (error) => {
    assert(
      error instanceof MilestoneStateError && error.reason === "already_open",
      "already open",
    );
  },
);
await expectThrow(
  () =>
    milestoneService.closeMilestone(admin, {
      orgId,
      milestoneId: closedEarly.id,
      moveOpenIssuesTo: null,
    }),
  MilestoneStateError,
  (error) => {
    assert(
      error instanceof MilestoneStateError && error.reason === "closed",
      "close again",
    );
  },
);

const capProject = await makeProject("cap", "CAP");
const capIds: string[] = [];
for (let index = 0; index < MAX_OPEN_MILESTONES_PER_PROJECT; index += 1) {
  const created = await milestoneService.createMilestone(member, {
    orgId,
    projectId: capProject.id,
    name: `cap-${index}`,
    targetDate: null,
  });
  capIds.push(created.id);
}
await expectThrow(
  () =>
    milestoneService.createMilestone(member, {
      orgId,
      projectId: capProject.id,
      name: "cap-overflow",
      targetDate: null,
    }),
  MilestoneStateError,
  (error) => {
    assert(
      error instanceof MilestoneStateError && error.reason === "too_many_open",
      "cap",
    );
  },
);
const capList = await milestoneService.listMilestones(member, orgId, capProject.id);
assert(capList.length === MAX_OPEN_MILESTONES_PER_PROJECT, "cap did not insert");
const closedCap = await milestoneService.closeMilestone(admin, {
  orgId,
  milestoneId: capIds[0]!,
  moveOpenIssuesTo: null,
});
assert(closedCap.movedIssueIds.length === 0, "nothing to move");
const replacement = await milestoneService.createMilestone(member, {
  orgId,
  projectId: capProject.id,
  name: "cap-replacement",
  targetDate: null,
});
await expectThrow(
  () => milestoneService.reopenMilestone(member, orgId, capIds[0]!),
  MilestoneStateError,
  (error) => {
    assert(
      error instanceof MilestoneStateError && error.reason === "too_many_open",
      "reopen cap",
    );
  },
);
await milestoneService.closeMilestone(admin, {
  orgId,
  milestoneId: replacement.id,
  moveOpenIssuesTo: null,
});
const reopened = await milestoneService.reopenMilestone(member, orgId, capIds[0]!);
assert(reopened.closedAt === null, "reopened");
await expectThrow(
  () =>
    milestoneService.createMilestone(member, {
      orgId,
      projectId: capProject.id,
      name: "cap-0",
      targetDate: null,
    }),
  MilestoneStateError,
  (error) => {
    assert(
      error instanceof MilestoneStateError && error.reason === "name_taken",
      "closed name stays taken",
    );
  },
);

const work = await makeProject("work", "WRK");
const ship = await milestoneService.createMilestone(member, {
  orgId,
  projectId: work.id,
  name: "Ship",
  targetDate: past,
});
const next = await milestoneService.createMilestone(member, {
  orgId,
  projectId: work.id,
  name: "Next",
  targetDate: later,
});
const drop = await milestoneService.createMilestone(member, {
  orgId,
  projectId: work.id,
  name: "Drop",
  targetDate: null,
});

const beforeIssues = issueRows().length;
const createdBefore = issueCreatedEvents.length;
await expectThrow(
  () =>
    issueService.createIssue(member, {
      ...issueInput(orgId, work.id, { title: "Should not exist" }),
      milestoneId: closedEarly.id,
    }),
  NotFoundError,
);
await expectThrow(
  () =>
    issueService.createIssue(member, {
      ...issueInput(orgId, work.id, { title: "Closed target" }),
      milestoneId: capIds[1] ? drop.id : drop.id,
    }),
  MilestoneStateError,
);
// The second call used an open milestone. Recreate the refusal with a closed one.
await milestoneService.closeMilestone(admin, {
  orgId,
  milestoneId: drop.id,
  moveOpenIssuesTo: null,
});
await expectThrow(
  () =>
    issueService.createIssue(member, {
      ...issueInput(orgId, work.id, { title: "Closed milestone" }),
      milestoneId: drop.id,
    }),
  MilestoneStateError,
  (error) => {
    assert(
      error instanceof MilestoneStateError && error.reason === "closed",
      "create into closed",
    );
  },
);
assert(issueRows().length === beforeIssues, "refused create inserted an issue");
assert(
  issueCreatedEvents.length === createdBefore,
  "refused create announced issue.created",
);

async function makeIssue(
  title: string,
  milestoneId: typeof ship.id | null,
  assignee: typeof tenant.userIds.member | null,
) {
  return issueService.createIssue(member, {
    ...issueInput(orgId, work.id, { title, assigneeId: assignee }),
    milestoneId,
  });
}

const openMember = await makeIssue("Open member", ship.id, tenant.userIds.member);
const openAdmin = await makeIssue("Open admin", ship.id, tenant.userIds.admin);
const openNone = await makeIssue("Open none", ship.id, null);
const doneIssue = await makeIssue("Done", ship.id, tenant.userIds.member);
await issueService.changeIssueStatus(member, {
  orgId,
  issueId: doneIssue.id,
  status: "done",
});
const canceledIssue = await makeIssue("Canceled", ship.id, null);
await issueService.changeIssueStatus(member, {
  orgId,
  issueId: canceledIssue.id,
  status: "canceled",
});
const archivedOpen = await makeIssue(
  "Archived open",
  ship.id,
  tenant.userIds.member,
);
await issueService.archiveIssue(member, orgId, archivedOpen.id);
const archivedDone = await makeIssue("Archived done", ship.id, tenant.userIds.member);
await issueService.changeIssueStatus(member, {
  orgId,
  issueId: archivedDone.id,
  status: "done",
});
await issueService.archiveIssue(member, orgId, archivedDone.id);
const outsider = await makeIssue("Outsider", null, tenant.userIds.member);

const shipView = await milestoneService.getMilestone(viewer, orgId, ship.id);
assert(shipView.progress.total === 4, `total ${shipView.progress.total}`);
assert(shipView.progress.open === 3, `open ${shipView.progress.open}`);
assert(shipView.progress.closed === 1, `closed ${shipView.progress.closed}`);
assert(shipView.progress.total === shipView.progress.open + shipView.progress.closed, "totals add");
assert(shipView.overdue === true, "past open milestone with open issues is overdue");

const noIssues = await milestoneService.createMilestone(member, {
  orgId,
  projectId: work.id,
  name: "Empty past",
  targetDate: past,
});
const emptyView = await milestoneService.getMilestone(member, orgId, noIssues.id);
assert(emptyView.overdue === false, "no open issues is not overdue");
const futureView = await milestoneService.getMilestone(member, orgId, next.id);
assert(futureView.overdue === false, "future is not overdue");

const doneOnly = await milestoneService.createMilestone(member, {
  orgId,
  projectId: work.id,
  name: "Done only",
  targetDate: past,
});
const finished = await makeIssue("Finished only", doneOnly.id, tenant.userIds.member);
await issueService.changeIssueStatus(member, {
  orgId,
  issueId: finished.id,
  status: "done",
});
const doneView = await milestoneService.getMilestone(member, orgId, doneOnly.id);
assert(doneView.progress.open === 0 && doneView.progress.closed === 1, "done counts closed");
assert(doneView.overdue === false, "no remaining open work is not overdue");

const alertsBefore = milestoneAlerts().length;
const closedBefore = closedEvents.length;
const updatedBefore = issueUpdatedEvents.length;
const auditsBeforeClose = audits("milestone.closed").length;

await expectThrow(
  () =>
    milestoneService.closeMilestone(admin, {
      orgId,
      milestoneId: ship.id,
      moveOpenIssuesTo: ship.id,
    }),
  NotFoundError,
);
await expectThrow(
  () =>
    milestoneService.closeMilestone(admin, {
      orgId,
      milestoneId: ship.id,
      moveOpenIssuesTo: otherName.id,
    }),
  NotFoundError,
);
await expectThrow(
  () =>
    milestoneService.closeMilestone(admin, {
      orgId,
      milestoneId: ship.id,
      moveOpenIssuesTo: closedEarly.id,
    }),
  NotFoundError,
);
const closedOther = await milestoneService.createMilestone(member, {
  orgId,
  projectId: otherProject.id,
  name: "Closed elsewhere",
  targetDate: null,
});
await milestoneService.closeMilestone(admin, {
  orgId,
  milestoneId: closedOther.id,
  moveOpenIssuesTo: null,
});
await expectThrow(
  () =>
    milestoneService.closeMilestone(admin, {
      orgId,
      milestoneId: ship.id,
      moveOpenIssuesTo: closedOther.id,
    }),
  NotFoundError,
);
await expectThrow(
  () =>
    milestoneService.closeMilestone(admin, {
      orgId,
      milestoneId: ship.id,
      moveOpenIssuesTo: drop.id,
    }),
  MilestoneStateError,
  (error) => {
    assert(
      error instanceof MilestoneStateError && error.reason === "closed",
      "closed target",
    );
  },
);

const shipStill = await milestoneService.getMilestone(member, orgId, ship.id);
assert(shipStill.milestone.closedAt === null, "refused close stayed open");
assert(
  (await issueService.getIssue(member, orgId, openMember.id)).milestoneId === ship.id,
  "refused close left the issue",
);
assert(milestoneAlerts().length === alertsBefore, "refused close alerted");
assert(closedEvents.length === closedBefore, "refused close emitted");
assert(audits("milestone.closed").length === auditsBeforeClose, "refused close audited");

const closedShip = await milestoneService.closeMilestone(admin, {
  orgId,
  milestoneId: ship.id,
  moveOpenIssuesTo: next.id,
});
assert(
  [...closedShip.movedIssueIds].sort().join() ===
    [openMember.id, openAdmin.id, openNone.id].sort().join(),
  `moved ${closedShip.movedIssueIds.join(",")}`,
);
assert(closedShip.milestone.closedAt !== null, "closed");
assert(closedEvents.length === closedBefore + 1, "one closed event");
const closedPayload = closedEvents.at(-1) as {
  movedToMilestoneId: string | null;
  movedIssueIds: readonly string[];
  actorId: string;
  projectId: string;
};
assert(closedPayload.movedToMilestoneId === next.id, "event target");
assert(closedPayload.actorId === admin.userId, "event actor");
assert(closedPayload.projectId === work.id, "event project");
assert(issueUpdatedEvents.length === updatedBefore, "close does not emit issue.updated");

assert(
  (await issueService.getIssue(member, orgId, openMember.id)).milestoneId === next.id,
  "member issue moved",
);
assert(
  (await issueService.getIssue(member, orgId, openAdmin.id)).milestoneId === next.id,
  "admin issue moved",
);
assert(
  (await issueService.getIssue(member, orgId, openNone.id)).milestoneId === next.id,
  "unassigned issue moved",
);
assert(
  (await issueService.getIssue(member, orgId, doneIssue.id)).milestoneId === ship.id,
  "done issue stayed",
);
assert(
  (await issueService.getIssue(member, orgId, canceledIssue.id)).milestoneId === ship.id,
  "canceled issue stayed",
);
assert(
  (await issueService.getIssue(member, orgId, archivedOpen.id)).milestoneId === ship.id,
  "archived issue stayed",
);
assert(
  (await issueService.getIssue(member, orgId, outsider.id)).milestoneId === null,
  "other issue stayed out",
);

const alerts = milestoneAlerts().slice(alertsBefore);
assert(alerts.length === 1, `alerts ${alerts.length}`);
assert(alerts[0]?.recipientId === tenant.userIds.member, "assignee alerted");
assert(alerts[0]?.actorId === admin.userId, "actor recorded on the alert");
assert(
  alerts.every((row) => row.recipientId !== admin.userId),
  "closer was alerted",
);

const afterShip = await milestoneService.getMilestone(member, orgId, ship.id);
assert(afterShip.overdue === false, "closed milestone is not overdue");
assert(afterShip.progress.open === 0, `remaining open ${afterShip.progress.open}`);
assert(afterShip.progress.closed === 2, `remaining closed ${afterShip.progress.closed}`);
const nextView = await milestoneService.getMilestone(member, orgId, next.id);
assert(nextView.progress.open === 3, `target open ${nextView.progress.open}`);
assert(nextView.overdue === false, "future target is not overdue");

const loose = await makeIssue("Loose", drop.id, null);
await milestoneService.reopenMilestone(member, orgId, drop.id);
const movedOut = await milestoneService.setIssueMilestone(member, {
  orgId,
  issueId: loose.id,
  milestoneId: drop.id,
});
assert(movedOut.milestoneId === drop.id, "set milestone");
const takenOut = await milestoneService.setIssueMilestone(member, {
  orgId,
  issueId: loose.id,
  milestoneId: null,
});
assert(takenOut.milestoneId === null, "cleared milestone");
await milestoneService.setIssueMilestone(viewer, {
  orgId,
  issueId: outsider.id,
  milestoneId: next.id,
});
assert(
  (await issueService.getIssue(viewer, orgId, outsider.id)).milestoneId === next.id,
  "assignee viewer can move their issue",
);

await expectThrow(
  () =>
    milestoneService.setIssueMilestone(member, {
      orgId,
      issueId: loose.id,
      milestoneId: ship.id,
    }),
  MilestoneStateError,
  (error) => {
    assert(
      error instanceof MilestoneStateError && error.reason === "closed",
      "set closed",
    );
  },
);
assert(
