function fail(message: string): never {
  throw new Error(message);
}

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) fail(message);
}

async function expectThrow(
  run: () => Promise<unknown>,
  ctor: new (...args: never[]) => Error,
  check?: (error: Error) => void,
): Promise<void> {
  try {
    await run();
  } catch (error) {
    if (!(error instanceof ctor)) {
      fail(
        `expected ${ctor.name}, got ${error instanceof Error ? error.stack : String(error)}`,
      );
    }
    check?.(error);
    return;
  }
  fail(`expected ${ctor.name}, got a result`);
}

function audits(action?: string) {
